1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
36	
37	export interface ScenarioResult {
38	  results: StepResult[];
39	}
40	
41	// ---------------------------------------------------------------------------
42	// Shared arithmetic — used by both the premium and the claim side.
43	// ---------------------------------------------------------------------------
44	
45	// Percentages MUST go through this helper. Multiplying first and dividing by
46	// 100 afterwards keeps the arithmetic drift-free; the tempting `amount * 0.5`
47	// (or `* 1.1`) introduces binary-fraction error — 100 * 1.1 yields
48	// 110.00000000000001 — and since the spec rounds premiums UP at the very end
49	// that drift becomes a whole extra G.
50	const percentOf = (amount: number, percent: number): number => (amount * percent) / 100;
51	
52	// Each item-level surcharge is "a percentage of this item's base premium, or
53	// nothing at all", so the condition is the only part that varies.
54	const percentOfWhen = (applies: boolean, amount: number, percent: number): number =>
55	  applies ? percentOf(amount, percent) : 0;
56	
57	// The MHPCO rounds in its own favour. That is ONE rule, but "its favour" points
58	// in opposite directions on the two sides of the business: a premium is money
59	// coming in, so a fraction rounds UP; a payout is money going out, so a fraction
60	// rounds DOWN. Naming both halves keeps the rule greppable and stops either call
61	// site from reading as an arbitrary choice of Math.ceil over Math.floor.
62	// They are deliberately two functions rather than one with a direction flag:
63	// `roundInMhpcosFavour(total, UP)` would hide at the call site exactly what the
64	// reader came there to learn.
65	const roundPremiumInMhpcosFavour = (amount: number): number => Math.ceil(amount);
66	const roundPayoutInMhpcosFavour = (amount: number): number => Math.floor(amount);
67	
68	// ---------------------------------------------------------------------------
69	// Premium side — quoting a policy.
70	// ---------------------------------------------------------------------------
71	
72	const PROCESSING_FEE = 5;
73	
74	const FIRST_INSURANCE_PERCENT = 10;
75	
76	const BASE_PREMIUMS: Record<string, number> = {
77	  sword: 100,
78	  amulet: 60,
79	  staff: 80,
80	  potion: 40,
81	  rune: 25,
82	  moonstone: 25,
83	};
84	
85	const BLOCK_SIZE = 3;
86	const BLOCK_BASE_PREMIUM = 60;
87	
88	const countByType = (items: Item[]): Map<string, number> => {
89	  const counts = new Map<string, number>();
90	  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
91	
92	  return counts;
93	};
94	
95	const basePremiumForType = (type: string, count: number): number =>
96	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
97	
98	const policyBasePremium = (items: Item[]): number =>
99	  [...countByType(items)]
100	    .map(([type, count]) => basePremiumForType(type, count))
101	    .reduce((total, premium) => total + premium, 0);
102	
103	const CURSE_PERCENT = 50;
104	
105	const HIGH_ENCHANTMENT_PERCENT = 30;
106	const HIGH_ENCHANTMENT_THRESHOLD = 5;
107	
108	const itemSurcharge = (item: Item): number => {
109	  const base = BASE_PREMIUMS[item.type];
110	  const curseSurcharge = percentOfWhen(item.cursed === true, base, CURSE_PERCENT);
111	  const highEnchantmentSurcharge = percentOfWhen(
112	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
113	    base,
114	    HIGH_ENCHANTMENT_PERCENT,
115	  );
116	
117	  return curseSurcharge + highEnchantmentSurcharge;
118	};
119	
120	const itemSurcharges = (items: Item[]): number =>
121	  items.reduce((total, item) => total + itemSurcharge(item), 0);
122	
123	// Every modifier is a percentage of a base premium, and they are SUMMED rather
124	// than compounded: the spec's worked example reads
125	// "100 G base + 50 G curse + 10 G first insurance = 160 G + 5 G fee = 165 G",
126	// so the first-insurance 10 % is taken on the policy base, not on the
127	// curse-inflated amount.
128	const LOYALTY_PERCENT = 20;
129	const LOYALTY_THRESHOLD_YEARS = 2;
130	
131	const FOLLOW_UP_PERCENT = 15;
132	
133	const quote = ({ items }: QuoteStep, customer: Customer, isFollowUp: boolean): StepResult => {
134	  const policyBase = policyBasePremium(items);
135	
136	  // Surcharges add to the policy base, discounts subtract from it. Both are
137	  // percentages OF THE POLICY BASE (never of each other) — see the note above.
138	  const firstInsuranceSurcharge = percentOf(policyBase, FIRST_INSURANCE_PERCENT);
139	  const loyaltyDiscount = percentOfWhen(
140	    customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
141	    policyBase,
142	    LOYALTY_PERCENT,
143	  );
144	
145	  const followUpDiscount = percentOfWhen(isFollowUp, policyBase, FOLLOW_UP_PERCENT);
146	
147	  const surcharges = itemSurcharges(items) + firstInsuranceSurcharge;
148	  const discounts = loyaltyDiscount + followUpDiscount;
149	  const total = policyBase + surcharges - discounts + PROCESSING_FEE;
150	
151	  return { premium: roundPremiumInMhpcosFavour(total) };
152	};
153	
154	// ---------------------------------------------------------------------------
155	// Claim side — settling a payout against an open policy.
156	// ---------------------------------------------------------------------------
157	
158	const INSURANCE_VALUES: Record<string, number> = {
159	  sword: 1000,
160	  amulet: 600,
161	  staff: 800,
162	  potion: 400,
163	  rune: 250,
164	  moonstone: 250,
165	};
166	
167	const DEDUCTIBLE = 100;
168	const CAP_MULTIPLIER = 2;
169	
170	interface Policy {
171	  items: Item[];
172	  remainingCap: number;
173	}
174	
175	const openPolicy = (items: Item[]): Policy => ({
176	  items,
177	  remainingCap:
178	    CAP_MULTIPLIER * items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0),
179	});
180	
181	// Settling a claim both answers the step and moves the policy on: successive
182	// claims draw down the same cap. Rather than writing through the caller's
183	// Policy, `claim` returns the policy it leaves behind, so the depletion is
184	// visible at the one place that owns the registry.
185	// The claim-side enchantment threshold (8) is deliberately NOT the premium-side
186	// one (5): a sword can be enchanted enough to cost more to insure without being
187	// enchanted enough to have its damage halved.
188	const HALVED_REIMBURSEMENT_THRESHOLD = 8;
189	const HALVED_REIMBURSEMENT_PERCENT = 50;
190	
191	// How much of a damage amount the policy covers, BEFORE the deductible — the
192	// caller subtracts that. Special clauses are written as guards in precedence
193	// order: the first one that matches decides, so a clause that must win over
194	// another is simply written above it.
195	const coveredAmount = (damage: Damage, item: Item): number => {
196	  const isHighlyEnchanted = (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_THRESHOLD;
197	  if (isHighlyEnchanted) return percentOf(damage.amount, HALVED_REIMBURSEMENT_PERCENT);
198	
199	  return damage.amount;
200	};
201	
202	// What a single damage entry is worth on its own: the covered amount that the
203	// item's clauses allow, less the deductible that every damaged item carries.
204	const payoutForDamage = (damage: Damage, items: Item[]): number => {
205	  const item = items.find(({ type }) => type === damage.itemType) as Item;
206	
207	  return coveredAmount(damage, item) - DEDUCTIBLE;
208	};
209	
210	const claim = (
211	  { incident }: ClaimStep,
212	  policy: Policy,
213	): { result: StepResult; policy: Policy } => {
214	  // Per-damage amounts stay fractional: the rounding wraps the SUMMED total, not
215	  // each entry, and happens before the cap clamp below so remainingCap stays whole.
216	  const desiredPayout = roundPayoutInMhpcosFavour(
217	    incident.damages.reduce((total, damage) => total + payoutForDamage(damage, policy.items), 0),
218	  );
219	
220	  // A damage below the deductible pays nothing; the MHPCO is stingy, not a
221	  // debt collector. Only the TOTAL is held at zero — whether a below-deductible
222	  // entry should offset a sibling entry in the same incident is unspecified.
223	  const owed = Math.max(0, desiredPayout);
224	
225	  // The policy pays at most what is left of its cap; the excess is simply lost.
226	  const payout = Math.min(owed, policy.remainingCap);
227	  const remainingCap = policy.remainingCap - payout;
228	
229	  return { result: { payout, remainingCap }, policy: { ...policy, remainingCap } };
230	};
231	
232	// The follow-up discount is about contract number, so only quote steps count —
233	// interleaved claim steps must not make the next quote look like a follow-up.
234	const isFollowUpQuote = (steps: Step[], index: number): boolean =>
235	  steps.slice(0, index).some((earlier) => earlier.op === "quote");
236	
237	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
238	  // Policies opened by quote steps, keyed by the step index a later claim cites.
239	  // Claims draw the cap down, so this registry is the one piece of carried state.
240	  const policies = new Map<number, Policy>();
241	
242	  const results = steps.map((step, index) => {
243	    if (step.op === "quote") {
244	      policies.set(index, openPolicy(step.items));
245	
246	      return quote(step, customer, isFollowUpQuote(steps, index));
247	    }
248	
249	    const settled = claim(step, policies.get(step.policy) as Policy);
250	    policies.set(step.policy, settled.policy);
251	
252	    return settled.result;
253	  });
254	
255	  return { results };
256	};
